
import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { createRoot } from 'react-dom/client';
import { Bubble, Prompts } from '@ant-design/x';
import { Button, Flex, message as antMessage, Space, Spin, Modal } from 'antd';
import { BulbOutlined, BookOutlined, LoadingOutlined, FontSizeOutlined } from '@ant-design/icons';
import contextTagPng from '../icons/@content.png';
import loveMessageSvg from '../icons/love_message.svg';
import atIconSvg from '../icons/at.svg';
import viberoIconPng from '../icons/vibero.png';
import SlateInputWithSender from './SlateInputWithSender';
import zhipuAIService from './zhipuAIService';
import deepSeekService from './deepSeekService';
import geminiService from './geminiService';
import huoshanService from './huoshanService';
import customOpenAIService from './customOpenAIService';
import MarkdownRenderer from './MarkdownRenderer';
import './styles.css';

// 模型名称映射：将菜单 key 映射到实际的 API 模型名称或 Endpoint ID
const MODEL_NAME_MAP = {
    'GLM-4.6': 'ep-20260116144751-9ftv8', // 火山引擎 GLM endpoint ID
    'deepseek': 'ep-20260116144849-sg4bv', // 火山引擎 DeepSeek endpoint ID
    'gemini': 'gemini-2.5-flash',
    'doubao': 'ep-20260116143400-qz6rl' // 火山引擎 Doubao endpoint ID
};

// Vibero Logo
const viberoLogo = (
    <img src={viberoIconPng} width="40" height="40" alt="Vibero Logo" />
);

// 定义 roles 配置
const roles = {
    assistant: {
        placement: 'start',
        variant: 'shadow',
        loadingRender: () => (
            <Space>
                <Spin indicator={<LoadingOutlined style={{ fontSize: 20, color: 'var(--fill-primary)' }} spin />} size="small" />
            </Space>
        ),
    },
    user: {
        placement: 'end',
        variant: 'shadow',
    },
};

// 欢迎消息提示项配置（静态数据）
const welcomePromptItems = [
    {
        key: '1',
        icon: <BookOutlined style={{ color: '#1890FF' }} />,
        label: 'Canvas ⬅️ Chat',
        description: 'Drag AI chats to the canvas to generate Q&A flashcards.',
    },
    {
        key: '2',
        icon: <BulbOutlined style={{ color: '#FFD700' }} />,
        label: 'Canvas ➡️ Chat',
        description: (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '4px', marginTop: '4px' }}>
                <span style={{ fontWeight: 600, color: '#262626' }}>3 ways to chat with context:</span>
                <span>1️⃣ <span style={{ fontWeight: 600 }}>Cmd/Ctrl + Click</span> any paragraph</span>
                <span>2️⃣ <span style={{ fontWeight: 600 }}>Drag</span> Summary Card here</span>
                <span>3️⃣ <span style={{ fontWeight: 600 }}>Paste</span> Screenshot</span>
            </div>
        ),
    }
];

function AIChatApp() {
    // 消息状态（不包含欢迎消息）
    const [messages, setMessages] = useState([]);
    const [loading, setLoading] = useState(false);
    const [welcomeActionText, setWelcomeActionText] = useState('🤫 Sometimes AI has a surprise note for you. Take a peek!');
    const [loveActive, setLoveActive] = useState(false);
    const [isDragOver, setIsDragOver] = useState(false);
    const [draggedVibeCardId, setDraggedVibeCardId] = useState(null);
    const [historyLoaded, setHistoryLoaded] = useState(false);
    const messagesEndRef = useRef(null);
    const insertVibeCardRef = useRef(null);
    const mouseDownTargetRef = useRef(null);
    const [selectedConversations, setSelectedConversations] = useState(new Set());

    // 字体大小调整状态
    const [fontScale, setFontScale] = useState(() => {
        // 从 Zotero Prefs 读取保存的字体大小
        try {
            const Zotero = window.parent?.Zotero || window.Zotero;
            if (Zotero && Zotero.Prefs) {
                const saved = Zotero.Prefs.get('aiChat.fontScale', true);
                if (saved !== undefined && saved !== null) {
                    // console.log('[AIChat] 从 Prefs 读取字体大小:', saved);
                    return parseFloat(saved);
                }
            }
        } catch (e) {
            console.warn('[AIChat] 无法从 Prefs 读取字体大小:', e);
        }
        return 1.0;
    });
    const [showFontSlider, setShowFontSlider] = useState(false);

    // API Key 配置
    const [apiKey, setApiKey] = useState('');
    // 默认使用 doubao（豆包多模态模型，支持图片）
    const [selectedModel, setSelectedModel] = useState({ key: 'doubao', label: 'Doubao(多模态)' });
    const [deepSeekApiKey, setDeepSeekApiKey] = useState('');

    // 获取当前自定义模型配置（用于动态更新显示标签）
    const getCustomModelConfig = useCallback(() => {
        try {
            const Zotero = window.parent?.Zotero || window.Zotero;
            if (Zotero && Zotero.Prefs) {
                const saved = Zotero.Prefs.get('aiChat.customModelConfig', true);
                if (saved) {
                    return JSON.parse(saved);
                }
            }
        } catch (e) {
            console.warn('[AIChat] Failed to get custom model config:', e);
        }
        return null;
    }, []);

    // 计算实际显示的模型（custom model 时动态读取最新配置）
    const displayModel = useMemo(() => {
        if (selectedModel.key === 'custom') {
            const config = getCustomModelConfig();
            if (config && config.modelName) {
                return {
                    key: 'custom',
                    label: `Custom (${config.modelName})`,
                    config: config
                };
            }
        }
        return selectedModel;
    }, [selectedModel, getCustomModelConfig]);

    // 获取当前论文的 itemID
    const getItemID = useCallback(() => {
        return window.frameElement?.getAttribute('data-item-id');
    }, []);

    // 保存消息到数据库（只保存非欢迎消息）
    const saveMessagesToDB = useCallback(async (messagesToSave) => {
        const itemID = getItemID();
        if (!itemID) {
            console.warn('[AIChat] 无法保存：未找到 itemID');
            return;
        }

        try {
            // 过滤掉欢迎消息，只保存实际对话
            const filteredMessages = messagesToSave.filter(msg => !msg.isWelcome);

            // 序列化消息（移除 React 组件，只保留可序列化数据）
            const serializableMessages = filteredMessages.map(msg => ({
                id: msg.id,
                role: msg.role,
                content: typeof msg.content === 'string' ? msg.content : '[React Component]',
                vibeCardRefs: msg.vibeCardRefs || [],
                images: msg.images?.map(img => ({
                    // 保存完整的图片信息
                    name: img.name,
                    type: img.type,
                    r2Url: img.r2Url,       // R2 公开 URL
                    r2Key: img.r2Key,       // R2 文件 key
                    base64: img.base64      // Base64（用于本地显示）
                })) || [],
                timestamp: msg.timestamp || Date.now()
            }));

            await window.parent.Zotero.VibeDB.AIChats.save(parseInt(itemID), serializableMessages);
            // console.log(`[AIChat] ✓ 已保存 ${serializableMessages.length} 条消息到数据库`);
        } catch (error) {
            console.error('[AIChat] 保存消息失败:', error);
        }
    }, [getItemID]);

    // 从数据库加载历史消息（仅在组件初始化时调用一次）
    const loadHistoryFromDB = useCallback(async () => {
        const itemID = getItemID();
        if (!itemID) {
            // console.log('[AIChat] 未找到 itemID，跳过加载历史');
            setHistoryLoaded(true);
            return;
        }

        try {
            const result = await window.parent.Zotero.VibeDB.AIChats.get(parseInt(itemID));
            if (result && result.messages && Array.isArray(result.messages)) {
                // console.log(`[AIChat] ✓ 从数据库加载 ${result.messages.length} 条历史消息`);
                setMessages(result.messages);

                // 恢复 AI 服务的历史记录（转换为 AI 服务期望的格式）
                // 初始加载时默认使用火山引擎服务（因为默认模型是 doubao）
                const currentService = huoshanService;
                const serviceHistory = result.messages
                    .filter(msg => msg.role === 'user' || msg.role === 'assistant')
                    .map(msg => {
                        // 如果消息中有图片，重新构建多模态格式
                        if (msg.images && msg.images.length > 0) {
                            const messageContent = [
                                { type: 'text', text: msg.content }
                            ];
                            msg.images.forEach(img => {
                                // 优先使用 R2 URL，降级到 Base64
                                const imageUrl = img.r2Url || img.base64;
                                messageContent.push({
                                    type: 'image_url',
                                    image_url: { url: imageUrl }
                                });
                            });
                            return {
                                role: msg.role,
                                content: messageContent
                            };
                        }
                        // 纯文本消息直接使用
                        return {
                            role: msg.role,
                            content: msg.content
                        };
                    });

                if (serviceHistory.length > 0) {
                    currentService.setHistory(serviceHistory);
                    // console.log(`[AIChat] ✓ 已恢复 ${serviceHistory.length} 条 AI 服务历史`);
                }
            } else {
                // console.log('[AIChat] 数据库中无历史消息');
            }
        } catch (error) {
            console.error('[AIChat] 加载历史消息失败:', error);
        } finally {
            setHistoryLoaded(true);
        }
    }, [getItemID]); // 移除 selectedModel.key 依赖，避免模型切换时重新加载历史

    // 初始化时加载历史消息（仅执行一次）
    useEffect(() => {
        try {
            // API Key 已迁移到 Cloudflare Worker，不再需要在客户端设置
            // console.log('[AIChat] ✓ 使用 Cloudflare Worker 代理（API Key 已隐藏）');
        } catch (error) {
            console.warn('[AIChat] Error during initialization:', error);
        }

        // 加载历史消息
        loadHistoryFromDB();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []); // 空依赖数组，确保只在组件挂载时执行一次

    // 应用字体大小到 CSS 变量
    useEffect(() => {
        const scaleValue = fontScale.toString();
        document.documentElement.style.setProperty('--panel-font-scale', scaleValue);

        // 调试日志：检查各个元素的实际字体大小
        setTimeout(() => {
            const container = document.querySelector('.ai-chat-container');
            const bubble = document.querySelector('.ant-bubble-content');
            const header = document.querySelector('.ai-chat-header h3');

            // console.log('[AIChat] 字体缩放已设置:', {
            //     scale: fontScale,
            //     cssValue: scaleValue,
            //     computed: getComputedStyle(document.documentElement).getPropertyValue('--panel-font-scale'),
            //     containerFontSize: container ? getComputedStyle(container).fontSize : 'N/A',
            //     headerFontSize: header ? getComputedStyle(header).fontSize : 'N/A',
            //     bubbleFontSize: bubble ? getComputedStyle(bubble).fontSize : 'N/A'
            // });
        }, 100);
    }, [fontScale]);

    // 处理字体大小变化（用户手动调整滑块）
    const handleFontScaleChange = (value) => {
        console.log('[AIChat] 用户调整字体大小:', value);
        setFontScale(value);

        // 保存到 Zotero Prefs（使用 Char 类型）
        try {
            const Zotero = window.parent?.Zotero || window.Zotero;
            if (Zotero && Zotero.Prefs) {
                Zotero.Prefs.set('aiChat.fontScale', String(value), true);
                console.log('[AIChat] 已保存字体大小到 Prefs:', value);
            }
        } catch (e) {
            console.error('[AIChat] 保存字体大小到 Prefs 失败:', e);
        }
    };

    // 获取 VibeCard 内容
    const getVibeCardContent = async (vibeCardId) => {
        // console.log(`[VibeCard] 开始获取内容: ${vibeCardId}`);
        try {
            if (window.parent && window.parent.Zotero && window.parent.Zotero.VibeCard) {
                const itemID = getItemID();
                if (itemID) {
                    // console.log(`[VibeCard] 使用 itemID: ${itemID} 调用 Zotero.VibeCard.getContent(${vibeCardId})`);
                    const content = await window.parent.Zotero.VibeCard.getContent(vibeCardId, parseInt(itemID));
                    // console.log(`[VibeCard] 获取到内容 (长度: ${content?.length || 0})`);
                    return content || `[VibeCard ${vibeCardId} content]`;
                } else {
                    const content = await window.parent.Zotero.VibeCard.getContent(vibeCardId);
                    return content || `[VibeCard ${vibeCardId} content]`;
                }
            }
            return `[VibeCard ${vibeCardId} content]`;
        } catch (error) {
            console.error(`[VibeCard] 获取内容失败 ${vibeCardId}:`, error);
            return `[VibeCard ${vibeCardId}]`;
        }
    };

    // 渲染用户消息内容（支持 VibeCard chip 和图片）
    const renderUserMessageContent = (content, vibeCardRefs = [], images = []) => {
        const parts = [];

        // 先渲染图片
        if (images && images.length > 0) {
            parts.push(
                <div
                    key="images"
                    style={{
                        display: 'flex',
                        flexWrap: 'wrap',
                        gap: 8,
                        marginBottom: content ? 8 : 0
                    }}
                >
                    {images.map((img, idx) => (
                        <img
                            key={`img-${idx}`}
                            src={img.base64}
                            alt={img.name || 'image'}
                            style={{
                                maxWidth: 150,
                                maxHeight: 150,
                                borderRadius: 6,
                                objectFit: 'cover',
                            }}
                        />
                    ))}
                </div>
            );
        }

        // 如果没有 VibeCard 引用，直接返回文本
        if (!vibeCardRefs || vibeCardRefs.length === 0) {
            if (content) parts.push(content);
            return parts.length > 0 ? <>{parts}</> : content;
        }

        // 处理 VibeCard 引用
        const textParts = [];
        let lastIndex = 0;
        const nameToRefMap = {};
        vibeCardRefs.forEach(ref => {
            nameToRefMap[ref.name || ref.id] = ref;
        });

        const regex = /@([\w_]+)/g;
        let match;

        while ((match = regex.exec(content)) !== null) {
            const matchedName = match[1];
            const vibeCardRef = nameToRefMap[matchedName];

            if (vibeCardRef) {
                if (match.index > lastIndex) {
                    textParts.push(content.substring(lastIndex, match.index));
                }
                textParts.push(
                    <span
                        key={`chip-${vibeCardRef.id}-${match.index}`}
                        style={{
                            display: 'inline-block',
                            padding: '2px 6px',
                            margin: '0 2px',
                            borderRadius: '12px',
                            backgroundColor: '#f5f5f5',
                            border: '1px solid #e5e5e5',
                            color: '#262626',
                            fontSize: '0.9em',
                            fontWeight: '500',
                        }}
                    >
                        @{vibeCardRef.name || vibeCardRef.id}
                    </span>
                );
                lastIndex = regex.lastIndex;
            }
        }

        if (lastIndex < content.length) {
            textParts.push(content.substring(lastIndex));
        }

        // 合并图片和文本部分
        if (textParts.length > 0) {
            parts.push(<span key="text">{textParts}</span>);
        }

        return <>{parts}</>;
    };

    // 自动滚动到底部
    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages]);

    // 发送消息处理
    const handleSend = async (text, vibeCardRefs = [], images = []) => {
        // 立刻设置 loading 状态，让 UI 立刻响应
        setLoading(true);

        // 检查多模态支持：只有 Doubao 支持图片输入
        // 如果选择了非 Doubao 模型，需要检查当前消息或历史记录中是否包含图片
        if (selectedModel.key !== 'doubao') {
            // 检查当前消息是否包含图片
            const hasImageInCurrentMessage = images && images.length > 0;

            // 检查历史记录中是否有图片
            const hasImageInHistory = messages.some(msg =>
                msg.images && msg.images.length > 0
            );

            if (hasImageInCurrentMessage || hasImageInHistory) {
                console.warn('[AIChat] ⚠️ 非多模态模型不支持图片输入:', {
                    model: selectedModel.key,
                    hasImageInCurrentMessage,
                    hasImageInHistory
                });

                // 显示友好错误提示
                antMessage.error({
                    content: `当前模型 ${selectedModel.label} 不支持图片输入，请切换到「Doubao(多模态)」模型`,
                    duration: 5,
                    style: { marginTop: '20vh' }
                });

                setLoading(false);
                return false; // 阻止发送
            }
        }

        // 余额检查：仅对非 custom model 进行（custom model 使用用户自己的 API Key）
        if (selectedModel.key !== 'custom') {
            try {
                const Zotero = window.Zotero || window.parent?.Zotero || window.top?.Zotero;
                if (Zotero && Zotero.VibeDBSync) {
                    const balance = await Zotero.VibeDBSync.getUserBalance();
                    const chatCost = Zotero.VibeDBSync.PRICING?.CHAT || 1;
                    if (!balance || balance.credits === null || balance.credits === undefined) {
                        antMessage.error('无法获取Credits信息，请稍后重试');
                        setLoading(false);
                        return false;
                    }

                    if (balance.credits < chatCost) {
                        antMessage.error(`Credits不足（需要 ${chatCost} Credits，剩余 ${balance.credits} Credits）`);
                        setLoading(false);
                        return false;
                    }
                }
            } catch (e) {
                console.error('[AIChat] 余额检查失败:', e);
                antMessage.error('余额检查失败，请稍后重试');
                setLoading(false);
                return false;
            }
        }

        // 获取当前论文的 Markdown 内容（先检查，不立即添加消息）
        const itemID = getItemID();
        // 根据选择的模型获取对应的 AI 服务
        // GLM-4.6、deepseek、doubao 都使用火山引擎服务
        // 根据选择的模型获取对应的 AI 服务
        // GLM-4.6、deepseek、doubao 都使用火山引擎服务
        let currentService;

        if (selectedModel.key === 'custom') {
            try {
                // 从 Zotero.Prefs 读取自定义模型配置
                const Zotero = window.parent?.Zotero || window.Zotero;
                let configStr = null;
                if (Zotero && Zotero.Prefs) {
                    configStr = Zotero.Prefs.get('aiChat.customModelConfig', true);
                }
                if (!configStr) {
                    antMessage.error('请先点击模型菜单右侧设置按钮配置自定义模型');
                    setLoading(false);
                    return false;
                }
                const config = JSON.parse(configStr);
                // 这里我们做个映射，把 form 里的字段映射到 service 需要的字段
                // form: baseUrl, apiKey, modelName
                // service: baseUrl, apiKey, model
                customOpenAIService.setConfig({
                    baseUrl: config.baseUrl,
                    apiKey: config.apiKey,
                    model: config.modelName
                });
                currentService = customOpenAIService;
            } catch (e) {
                console.error('Failed to load custom config', e);
                antMessage.error('自定义模型配置加载失败');
                setLoading(false);
                return false;
            }
        } else {
            currentService = (selectedModel.key === 'GLM-4.6' ||
                selectedModel.key === 'deepseek' ||
                selectedModel.key === 'doubao')
                ? huoshanService
                : selectedModel.key === 'gemini'
                    ? geminiService
                    : huoshanService; // 默认使用火山引擎
        }
        const hasPaperContext = currentService.hasPaperContext();

        // 如果还没有论文上下文，尝试获取
        if (itemID && window.parent?.Zotero?.VibeCard && !hasPaperContext) {
            try {
                // console.log(`[AIChat] 获取论文上下文: itemID=${itemID}`);
                const paperMarkdown = await window.parent.Zotero.VibeCard.getMarkdownContent(parseInt(itemID));

                if (!paperMarkdown) {
                    // 论文还没解析完成，显示自定义 Modal 提示
                    console.warn('[AIChat] ⚠️ 论文 Markdown 为空，可能还在解析中');
                    Modal.confirm({
                        title: null,
                        content: '请先解析论文',
                        okText: '确定',
                        cancelButtonProps: { style: { display: 'none' } },
                        centered: true,
                        width: 200,
                        bodyStyle: {
                            textAlign: 'center'
                        },
                        okButtonProps: {
                            style: {
                                backgroundColor: '#262626',
                                borderColor: '#262626',
                                color: '#ffffff',
                                fontWeight: 500,
                                height: '28px',
                                borderRadius: '6px',
                                fontSize: '13px'
                            }
                        },
                        modalRenderToBody: true,
                        style: {
                            borderRadius: '8px'
                        },
                        wrapClassName: 'ai-chat-modal'
                    });
                    setLoading(false);
                    return false; // 不继续处理，消息保留在输入框
                }

                // 论文已解析，设置上下文
                currentService.setPaperContext(paperMarkdown);
                // console.log(`[AIChat] ✓ 已设置论文上下文`);

            } catch (error) {
                console.error('[AIChat] 获取论文 Markdown 失败:', error);
                Modal.confirm({
                    title: null,
                    content: '请先解析论文',
                    okText: '确定',
                    cancelButtonProps: { style: { display: 'none' } },
                    centered: true,
                    width: 240,
                    bodyStyle: {
                        textAlign: 'center'
                    },
                    okButtonProps: {
                        style: {
                            backgroundColor: '#262626',
                            borderColor: '#262626',
                            color: '#ffffff',
                            fontWeight: 500,
                            height: '30px',
                            borderRadius: '6px',
                            fontSize: '14px'
                        }
                    },
                    modalRenderToBody: true,
                    style: {
                        borderRadius: '8px'
                    },
                    wrapClassName: 'ai-chat-modal'
                });
                setLoading(false);
                return false; // 不继续处理，消息保留在输入框
            }
        }

        // 论文上下文已准备好，现在添加用户消息
        const userMessage = {
            id: Date.now(),
            role: 'user',
            content: text,
            vibeCardRefs: vibeCardRefs,
            images: images, // 添加图片数据
            timestamp: Date.now()
        };

        // 替换 VibeCard 引用为实际内容
        let processedText = text;
        if (vibeCardRefs && vibeCardRefs.length > 0) {
            for (const vibeCardRef of vibeCardRefs) {
                const content = await getVibeCardContent(vibeCardRef.id);
                const regex = new RegExp(`@${vibeCardRef.name}`, 'g');
                processedText = processedText.replace(regex, `\n[引用内容开始]\n${content}\n[引用内容结束]\n`);
            }
        }

        // 构建消息内容：支持文本和图片的多模态格式
        let messageContent = processedText;
        if (images && images.length > 0) {
            // 构建多模态消息：文本 + 图片（使用 R2 公开 URL）
            messageContent = [
                { type: 'text', text: processedText }
            ];
            // 添加图片到消息内容（优先使用 R2 URL）
            images.forEach((img, idx) => {
                const imageUrl = img.r2Url || img.base64; // 优先使用 R2 URL，降级到 Base64
                messageContent.push({
                    type: 'image_url',
                    image_url: {
                        url: imageUrl
                    }
                });
            });
        }

        // 创建 AI 消息占位符
        const aiMessageId = Date.now() + 1;
        const aiMessage = {
            id: aiMessageId,
            role: 'assistant',
            content: '',
            typing: true,
            timestamp: Date.now()
        };

        // 合并更新消息状态（使用函数式更新，确保基于最新状态）
        // 同时也避免了中间状态（只有 user message 没有 AI placeholder）的渲染
        setMessages(prev => [...prev, userMessage, aiMessage]);

        // 注意：这里去掉了 setLoading(true) 因为在函数开始时已经设置了

        const performChat = async () => {
            try {
                // 使用当前选择的 AI 服务（流式输出）
                // 如果有图片，发送多模态内容；否则发送纯文本
                await currentService.chatStream(
                    messageContent,
                    ({ done, content, fullMessage, interrupted, error }) => {
                        if (!done && content) {
                            // 流式更新消息内容
                            setMessages(prev => prev.map(msg =>
                                msg.id === aiMessageId
                                    ? { ...msg, content: fullMessage, typing: true }
                                    : msg
                            ));
                        } else if (done) {
                            // 流式输出完成
                            let finalContent = fullMessage;

                            if (interrupted) {
                                const interruptReason = error
                                    ? `\n\n---\n\n⚠️ **回答被中断**: ${error}`
                                    : '\n\n---\n\n⚠️ **回答可能不完整**（连接中断或达到长度限制）';
                                finalContent += interruptReason;
                            }

                            // 更新最终消息
                            const finalAIMessage = {
                                id: aiMessageId,
                                role: 'assistant',
                                content: finalContent,
                                typing: false,
                                interrupted,
                                timestamp: Date.now()
                            };

                            setMessages(prev => {
                                const updatedMessages = prev.map(msg =>
                                    msg.id === aiMessageId ? finalAIMessage : msg
                                );

                                // AI 回复完成后保存到数据库
                                saveMessagesToDB(updatedMessages);

                                return updatedMessages;
                            });

                            // AI 回复成功，扣减对话余额（异步执行，不阻塞UI）
                            // 注意：Custom Model 使用用户自己的 API Key，不消耗平台余额
                            if (selectedModel.key !== 'custom') {
                                (async () => {
                                    try {
                                        const Zotero = window.Zotero || window.parent?.Zotero || window.top?.Zotero;
                                        if (Zotero && Zotero.VibeDBSync && Zotero.VibeDBSync.deductCredits) {
                                            const chatCost = Zotero.VibeDBSync.PRICING?.CHAT || 1;
                                            const success = await Zotero.VibeDBSync.deductCredits(chatCost);
                                            if (success) {
                                                // console.log('[AIChat] ✅ Credits已扣减');
                                            } else {
                                                console.error('[AIChat] ⚠️ 扣减Credits失败（但不影响对话继续）');
                                            }
                                        }
                                    } catch (e) {
                                        console.error('[AIChat] 扣减对话余额异常:', e);
                                    }
                                })();
                            } else {
                                // console.log('[AIChat] ℹ️ 使用自定义模型，不扣减对话余额');
                            }

                            if (interrupted) {
                                antMessage.warning('AI 回答可能不完整，请重试或缩短问题');
                            }

                            // 重置 loading 状态
                            setLoading(false);
                        }
                    },
                    {
                        includeHistory: true,
                        model: MODEL_NAME_MAP[selectedModel.key] || selectedModel.key,
                        systemPrompt: '你是 Vibero 的 AI 助手，专门帮助用户阅读和理解学术论文。请用简洁、专业的语言回答问题。\n\n格式要求：\n1. 使用 Markdown 格式输出\n2. 数学公式必须用标准 LaTeX 分隔符：\n   - 行内公式用 $...$ 包裹，如：$\\mathbf{p}_i$\n   - 块级公式用 $...$ 包裹\n3. 代码块使用 ```语言名 包裹'
                    }
                );
            } catch (error) {
                console.error('[AIChat] Error sending message:', error);

                // 构建友好的错误提示
                let errorContent = `❌ **发生错误**\n\n${error.message}`;

                // 添加具体的建议
                if (error.message.includes('不支持图片输入')) {
                    errorContent += '\n\n💡 **建议**: 请点击输入框底部的模型选择按钮，切换到「Doubao」模型后重试。';
                } else if (error.message.includes('图片无法访问')) {
                    errorContent += '\n\n💡 **建议**: 请删除图片后重新上传或截图。';
                } else if (error.message.includes('API Key')) {
                    errorContent += '\n\n💡 **建议**: 请在设置中检查 API Key 配置。';
                } else if (error.message.includes('超限')) {
                    errorContent += '\n\n💡 **建议**: 请稍候再试，或者缩短问题内容。';
                } else if (error.message.includes('网络')) {
                    errorContent += '\n\n💡 **建议**: 请检查网络连接并重试。';
                } else if (error.message.includes('超时')) {
                    errorContent += '\n\n💡 **建议**: 网络连接不稳定，请重试或稍后再试。';
                } else if (error.message.includes('服务器')) {
                    errorContent += '\n\n💡 **建议**: 服务器可能在维护中，请稍后再试。';
                }

                // 创建错误消息（只用于 UI 显示，不保存到数据库）
                const errorMessage = {
                    id: aiMessageId,
                    role: 'assistant',
                    content: errorContent,
                    typing: false,
                    isError: true,
                    timestamp: Date.now()
                };

                // 只在 UI 上显示错误消息，不保存到数据库
                setMessages(prev => {
                    const updatedMessages = prev.map(msg =>
                        msg.id === aiMessageId ? errorMessage : msg
                    );
                    // 不调用 saveMessagesToDB()，这样错误消息就不会被保存
                    return updatedMessages;
                });

                // 3秒后自动删除错误消息和用户消息（因为请求失败）
                setTimeout(() => {
                    setMessages(prev =>
                        prev.filter(msg => msg.id !== aiMessageId && msg.id !== messages[messages.length - 1]?.id)
                    );
                }, 3000);

                // 使用 Ant Design 的 message 组件显示通知
                antMessage.error({
                    content: error.message,
                    duration: 5,
                    style: {
                        marginTop: '20vh',
                    }
                });
            } finally {
                // 确保无论成功或失败都重置 loading 状态
                setLoading(false);
            }
        };

        performChat();
        return true;
    };

    // 插入 VibeCard 引用
    const insertVibeCardReference = (vibeCardData) => {
        if (insertVibeCardRef.current) {
            insertVibeCardRef.current(vibeCardData);
        }
    };

    // 暴露方法给全局 API
    useEffect(() => {
        globalInsertVibeCard = insertVibeCardReference;
        globalClearMessages = () => {
            setMessages([]);
        };
        globalSetDragOverState = (isDragging, vibeCardId) => {
            setIsDragOver(isDragging);
            setDraggedVibeCardId(isDragging ? vibeCardId : null);
        };
    }, [insertVibeCardReference]);

    // 记录鼠标按下时的目标元素，并动态设置 draggable
    const handleMouseDown = (event) => {
        mouseDownTargetRef.current = event.target;
        const isTextContent = event.target.closest('.ant-bubble-content');
        const container = event.currentTarget;

        if (isTextContent) {
            container.draggable = false;
        } else {
            container.draggable = true;
        }
    };

    // 处理从 PDF View 拖拽 VibeCard 到 AI Chat 的 drop 事件
    const handleVibeCardDrop = (event) => {
        event.preventDefault();
        event.stopPropagation();

        setIsDragOver(false);
        setDraggedVibeCardId(null);

        const vibeCardData = event.dataTransfer.getData('application/x-zotero-vibecard-reference');
        if (vibeCardData) {
            try {
                const data = JSON.parse(vibeCardData);
                if (data.vibeCardId && insertVibeCardRef.current) {
                    insertVibeCardRef.current({
                        id: data.vibeCardId,
                        name: data.vibeCardName || data.vibeCardId,
                        type: data.type,
                        vibeCardType: data.vibeCardType
                    });
                }
            } catch (error) {
                console.error('[AIChat] Error parsing VibeCard drop data:', error);
            }
        }
    };

    // 处理 dragover 事件以允许 drop
    const handleDragOver = (event) => {
        const types = event.dataTransfer.types;
        if (types.includes('application/x-zotero-vibecard-reference')) {
            event.preventDefault();
            event.dataTransfer.dropEffect = 'copy';
        }
    };

    // 处理对话选择
    const handleConversationClick = (event, conversationId) => {
        const isTextContent = event.target.closest('.ant-bubble-content');
        if (isTextContent) return;

        setSelectedConversations(prev => {
            const newSet = new Set(prev);
            if (newSet.has(conversationId)) {
                newSet.delete(conversationId);
            } else {
                newSet.add(conversationId);
            }
            return newSet;
        });
    };

    // 拖拽处理（支持多选）
    const handleDragStart = (event, conversationId, userMsg, aiMsg) => {
        let conversationsToDrag = [];

        if (selectedConversations.has(conversationId)) {
            for (let i = 0; i < messages.length - 1; i++) {
                const msg = messages[i];
                const nextMsg = messages[i + 1];
                if (msg.role === 'user' && nextMsg && nextMsg.role === 'assistant') {
                    const convId = `${msg.id}-${nextMsg.id}`;
                    if (selectedConversations.has(convId)) {
                        conversationsToDrag.push({
                            userText: msg.content,
                            aiText: nextMsg.content,
                            userVibeCardRefs: msg.vibeCardRefs || []
                        });
                    }
                }
            }
        } else {
            conversationsToDrag = [{
                userText: userMsg.content,
                aiText: aiMsg.content,
                userVibeCardRefs: userMsg.vibeCardRefs || []
            }];
        }

        const conversationData = {
            type: 'ai-chat-conversation',
            conversations: conversationsToDrag,
            timestamp: Date.now()
        };

        event.dataTransfer.setData('application/x-zotero-ai-conversation', JSON.stringify(conversationData));

        const plainText = conversationsToDrag
            .map(c => `Q: ${c.userText}\n\nA: ${c.aiText}`)
            .join('\n\n---\n\n');
        event.dataTransfer.setData('text/plain', plainText);

        event.dataTransfer.effectAllowed = 'copy';
        event.currentTarget.classList.add('dragging');
    };

    const handleDragEnd = (event) => {
        event.currentTarget.classList.remove('dragging');
        setSelectedConversations(new Set());
    };

    // 欢迎消息拖拽处理
    const handleWelcomeDragStart = (event) => {
        const welcomeContent = `Welcome to Vibero! 🚀 Enjoy your vibe reading trip!

**Canvas ⬅️ Chat**
Drag AI chats to the canvas to generate Q&A flashcards.

**Canvas ➡️ Chat**
3 ways to chat with context:
1️⃣ **Cmd/Ctrl + Click** any paragraph
2️⃣ **Drag** Summary Card here
3️⃣ **Paste** Screenshot`;

        const conversationData = {
            type: 'ai-chat-conversation',
            conversations: [{
                userText: 'How can I use Vibero AI Chat?',
                aiText: welcomeContent,
                userVibeCardRefs: []
            }],
            timestamp: Date.now()
        };

        event.dataTransfer.setData('application/x-zotero-ai-conversation', JSON.stringify(conversationData));

        const plainText = `Q: ${conversationData.conversations[0].userText}\n\nA: ${conversationData.conversations[0].aiText}`;
        event.dataTransfer.setData('text/plain', plainText);

        event.dataTransfer.effectAllowed = 'copy';
        event.currentTarget.classList.add('dragging');
    };

    // 模型切换处理
    const handleModelChange = (model) => {
        // console.log('[AIChat] 模型切换:', model);
        setSelectedModel(model);
    };

    // 清空对话历史
    const handleClearHistory = () => {
        Modal.confirm({
            title: '确认清空对话历史？',
            content: '此操作将清空当前所有对话记录和 AI 的上下文记忆。',
            okText: '确认',
            cancelText: '取消',
            onOk: async () => {
                // 清空所有 AI 服务历史
                huoshanService.clearHistory();
                geminiService.clearHistory();
                customOpenAIService.clearHistory();

                // 清空消息状态
                setMessages([]);

                // 清空数据库
                const itemID = getItemID();
                if (itemID) {
                    try {
                        await window.parent.Zotero.VibeDB.AIChats.save(parseInt(itemID), []);
                        // console.log('[AIChat] ✓ 数据库历史已清空');
                    } catch (error) {
                        console.error('[AIChat] 清空数据库失败:', error);
                    }
                }

                antMessage.success('对话历史已清空');
            }
        });
    };

    return (
        <div
            className="ai-chat-container"
            onDrop={handleVibeCardDrop}
            onDragOver={handleDragOver}
            style={{ position: 'relative' }}
        >
            {/* 拖拽悬停遮罩层 */}
            {isDragOver && (
                <div
                    className="drag-overlay"
                    style={{
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        zIndex: 9999,
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        justifyContent: 'center',
                        backgroundColor: 'rgba(255, 255, 255, 0.3)',
                        backdropFilter: 'blur(10px)',
                        WebkitBackdropFilter: 'blur(10px)',
                        pointerEvents: 'none',
                    }}
                >
                    <img
                        src={atIconSvg}
                        alt="@"
                        style={{ width: '80px', height: '80px', marginBottom: '16px' }}
                    />
                    <div style={{
                        fontSize: '20px',
                        fontWeight: 300,
                        color: '#262626',
                        marginBottom: '8px',
                    }}>
                        Drop content here to @!
                    </div>
                </div>
            )}

            {/* 头部 */}
            <div className="ai-chat-header">
                <Flex justify="space-between" align="center">
                    <h3>AI Chat</h3>
                    <Flex gap="small">
                        <Button
                            type="text"
                            size="small"
                            icon={<FontSizeOutlined />}
                            onClick={() => setShowFontSlider(!showFontSlider)}
                            title="调整字体大小"
                        />
                        <Button
                            type="text"
                            size="small"
                            onClick={handleClearHistory}
                            title="清空对话历史"
                        >
                            清空
                        </Button>
                    </Flex>
                </Flex>

                {/* 字体大小调整滑块 */}
                {showFontSlider && (
                    <div style={{
                        marginTop: '8px',
                        padding: '8px',
                        background: 'var(--fill-quinary)',
                        borderRadius: '6px',
                        border: '1px solid var(--fill-quaternary)'
                    }}>
                        <Flex gap="small" align="center">
                            <span style={{ fontSize: '12px', color: 'var(--fill-secondary)' }}>字体大小</span>
                            <input
                                type="range"
                                min="0.5"
                                max="2.0"
                                step="0.1"
                                value={fontScale}
                                onChange={(e) => handleFontScaleChange(parseFloat(e.target.value))}
                                style={{ flex: 1 }}
                            />
                            <span style={{
                                fontSize: '12px',
                                color: 'var(--fill-primary)',
                                minWidth: '3em',
                                textAlign: 'right'
                            }}>
                                {Math.round(fontScale * 100)}%
                            </span>
                            <Button
                                type="text"
                                size="small"
                                onClick={() => handleFontScaleChange(1.0)}
                                title="恢复默认"
                                style={{ fontSize: '12px', padding: '0 8px' }}
                            >
                                重置
                            </Button>
                        </Flex>
                    </div>
                )}
            </div>

            {/* 消息列表 */}
            <div className="ai-chat-messages">
                {/* 静态欢迎消息（始终显示，不存入 messages 状态，不可拖拽） */}
                {historyLoaded && (
                    <div
                        className="welcome-section"
                        draggable={true}
                        onDragStart={handleWelcomeDragStart}
                        onDragEnd={(e) => e.currentTarget.classList.remove('dragging')}
                    >
                        {/* Logo 和欢迎文字 */}
                        <div className="welcome-header">
                            <Bubble
                                placement="start"
                                variant="shadow"
                                content={
                                    <Flex gap="middle" align="center">
                                        {viberoLogo}
                                        <div>
                                            <div style={{ fontSize: 16, fontWeight: 500, color: '#262626' }}>
                                                Welcome to Vibero!
                                            </div>
                                            <div style={{ fontSize: 12, color: '#8c8c8c', marginTop: 4 }}>
                                                🚀 Enjoy your vibe reading trip!
                                            </div>
                                        </div>
                                    </Flex>
                                }
                            />
                        </div>

                        {/* 提示卡片（始终显示） */}
                        <div className="welcome-prompts-container">
                            <Prompts
                                vertical
                                items={welcomePromptItems}
                                styles={{
                                    list: { gap: 8 },
                                    item: {
                                        padding: '12px',
                                        border: '1px solid #f0f0f0',
                                        borderRadius: '6px',
                                        cursor: 'default',
                                        width: '100%',
                                        boxSizing: 'border-box'
                                    }
                                }}
                            />
                        </div>

                        {/* Action bar（只在没有对话时显示）
                        {messages.length === 0 && (
                            <div className="conversation-action-bar">
                                <Button
                                    type="text"
                                    size="small"
                                    icon={loveActive ? null : (
                                        <img src={loveMessageSvg} alt="love" style={{ width: 16, height: 16, display: 'block' }} />
                                    )}
                                    onClick={() => {
                                        setLoveActive(true);
                                        setTimeout(() => setLoveActive(false), 3000);
                                    }}
                                >
                                    {loveActive ? welcomeActionText : null}
                                </Button>
                            </div>
                        )} */}
                    </div>
                )}

                {/* 渲染对话消息 */}
                {messages.map((msg, index) => {
                    const isUserMsg = msg.role === 'user';
                    const nextMsg = messages[index + 1];
                    const isConversationPair = isUserMsg && nextMsg && nextMsg.role === 'assistant';

                    // 如果是对话对的开始，渲染整个对话容器
                    if (isConversationPair) {
                        const conversationId = `${msg.id}-${nextMsg.id}`;
                        const isSelected = selectedConversations.has(conversationId);

                        return (
                            <div
                                key={conversationId}
                                className={`conversation-container ${isSelected ? 'selected' : ''}`}
                                onMouseDown={handleMouseDown}
                                onClick={(e) => handleConversationClick(e, conversationId)}
                                onDragStart={(e) => handleDragStart(e, conversationId, msg, nextMsg)}
                                onDragEnd={handleDragEnd}
                            >
                                <div className={`conversation-messages ${nextMsg.isError ? 'error-message' : ''}`}>
                                    <Bubble.List
                                        roles={roles}
                                        items={[
                                            {
                                                key: msg.id,
                                                role: 'user',
                                                content: renderUserMessageContent(msg.content, msg.vibeCardRefs, msg.images),
                                            },
                                            {
                                                key: nextMsg.id,
                                                role: 'assistant',
                                                content: typeof nextMsg.content === 'string'
                                                    ? <MarkdownRenderer content={nextMsg.content} />
                                                    : nextMsg.content,
                                                loading: nextMsg.content === '' && loading && nextMsg.id === messages[messages.length - 1].id,
                                            },
                                        ]}
                                    />
                                </div>
                            </div>
                        );
                    }

                    // 如果是单独的 AI 消息
                    if (!isUserMsg && (index === 0 || messages[index - 1].role !== 'user')) {
                        return (
                            <div key={msg.id} className={`single-message ${msg.isError ? 'error-message' : ''}`}>
                                <Bubble.List
                                    roles={roles}
                                    items={[
                                        {
                                            key: msg.id,
                                            role: 'assistant',
                                            content: typeof msg.content === 'string'
                                                ? <MarkdownRenderer content={msg.content} />
                                                : msg.content,
                                            loading: msg.content === '' && loading && msg.id === messages[messages.length - 1].id,
                                        },
                                    ]}
                                />
                            </div>
                        );
                    }

                    return null;
                })}
                <div ref={messagesEndRef} />
            </div>

            {/* 输入区域 */}
            <div className="ai-chat-input-area">
                <SlateInputWithSender
                    onSubmit={handleSend}
                    loading={loading}
                    isDragOver={isDragOver}
                    draggedVibeCardId={draggedVibeCardId}
                    onVibeCardInsert={(insertFn) => {
                        insertVibeCardRef.current = insertFn;
                    }}
                    onModelChange={handleModelChange}
                    currentModel={displayModel}
                />
            </div>
        </div>
    );
}

// 全局引用，用于从外部调用
let globalInsertVibeCard = null;
let globalClearMessages = null;
let globalSetDragOverState = null;

// 安全地初始化全局 API
const initializeGlobalAPI = () => {
    if (typeof window !== 'undefined') {
        window.aiChatAPI = {
            insertVibeCardReference: (vibeCardData) => {
                if (globalInsertVibeCard) {
                    globalInsertVibeCard(vibeCardData);
                }
            },
            clearMessages: () => {
                if (globalClearMessages) {
                    globalClearMessages();
                }
            },
            setDragOverState: (isDragging, vibeCardId) => {
                if (globalSetDragOverState) {
                    globalSetDragOverState(isDragging, vibeCardId);
                }
            }
        };
    }
};

// 挂载到 DOM
const rootElement = document.getElementById('root');

if (!rootElement) {
    console.error('[AIChat] ❌ Root element not found!');
} else {
    try {
        const root = createRoot(rootElement);
        root.render(<AIChatApp />);
        initializeGlobalAPI();
    } catch (error) {
        console.error('[AIChat] ❌ Error mounting React app:', error);
    }
}
