/**
 * 图片上传到 Supabase Storage 工具函数
 * 
 * 使用阿里云 Supabase Edge Function 上传图片到 Storage
 * 用于 AI Chat 中上传截图/图片，获取公开 URL
 */
// Cloudflare R2 上传 Worker 地址（与 PDF 共用同一个 Worker 和 bucket）
// const R2_UPLOAD_WORKER_URL = "https://r2-pdf-upload.yuc430060.workers.dev";

// 阿里云 Supabase Edge Function 上传地址
// 阿里云 Supabase Edge Function 上传地址 (New OSS Endpoint)
const SUPABASE_UPLOAD_URL = "https://spb-wz98bgf6x7f3zs9b.supabase.opentrust.net/functions/v1/oss-image-upload";

/**
 * 将 Base64 Data URI 上传到 R2
 * @param {string} base64DataURI - Base64 格式的图片数据 (data:image/png;base64,...)
 * @param {string} fileName - 文件名（如 'screenshot_123456.png'）
 * @returns {Promise<{url: string, key: string}>} 上传结果，包含公开 URL
 */
export async function uploadImageToSupabase(base64DataURI, fileName = 'image.png') {
    console.log('[ImageUploader] 开始上传图片到 Supabase Storage');
    console.log('[ImageR2] 文件名:', fileName);
    console.log('[ImageR2] Data URI 前缀:', base64DataURI.substring(0, 50));

    try {
        // 1. 提取 MIME type 和 base64 数据
        const matches = base64DataURI.match(/^data:(.+?);base64,(.+)$/);
        if (!matches) {
            throw new Error('无效的 Base64 Data URI 格式');
        }

        const mimeType = matches[1]; // 如 'image/png'
        const base64Data = matches[2];

        console.log('[ImageR2] MIME Type:', mimeType);
        console.log('[ImageR2] Base64 数据长度:', base64Data.length);

        // 2. 将 Base64 转换为 Blob
        const binaryString = atob(base64Data);
        const bytes = new Uint8Array(binaryString.length);
        for (let i = 0; i < binaryString.length; i++) {
            bytes[i] = binaryString.charCodeAt(i);
        }
        const blob = new Blob([bytes], { type: mimeType });

        console.log('[ImageUploader] Blob 大小:', blob.size, 'bytes (', (blob.size / 1024).toFixed(2), 'KB)');

        // 3. 构建 FormData 上传
        const formData = new FormData();
        formData.append('file', blob, fileName);

        console.log('[ImageUploader] 正在上传到 Supabase...');
        const startTime = Date.now();

        // 4. 发送上传请求
        const response = await fetch(`${SUPABASE_UPLOAD_URL}/upload`, {
            method: 'POST',
            body: formData
        });

        const elapsed = Date.now() - startTime;
        console.log('[ImageUploader] 上传响应状态:', response.status, '(', elapsed, 'ms)');

        if (!response.ok) {
            const errorText = await response.text();
            console.error('[ImageUploader] 上传失败:', errorText);
            throw new Error(`Supabase 上传失败: ${response.status} - ${errorText}`);
        }

        // 5. 解析响应
        const result = await response.json();
        console.log('[ImageUploader] 上传响应:', result);

        if (!result.success) {
            throw new Error(result.error || 'Supabase 上传失败');
        }

        console.log('[ImageUploader] ✅ 上传成功！');
        console.log('[ImageUploader] 公开 URL:', result.url);
        console.log('[ImageUploader] 文件 Key:', result.key);

        // 直接使用 Worker 返回的 URL（Worker 会根据配置返回正确的公开 URL）
        return {
            url: result.url,
            key: result.key,
            proxyUrl: result.proxyUrl
        };

    } catch (error) {
        console.error('[ImageUploader] ❌ 上传失败:', error.message);
        throw error;
    }
}

/**
 * 从 Supabase Storage 删除图片（可选，用于清理）
 * @param {string} key - 文件 key
 */
export async function deleteImageFromSupabase(key) {
    try {
        console.log('[ImageUploader] 删除 Supabase 文件:', key);

        const response = await fetch(`${SUPABASE_UPLOAD_URL}/file/${key}`, {
            method: 'DELETE'
        });

        if (response.ok) {
            console.log('[ImageUploader] ✅ 文件已删除:', key);
            return true;
        } else {
            console.warn('[ImageUploader] ⚠️ 文件删除失败:', response.status);
            return false;
        }
    } catch (error) {
        console.warn('[ImageUploader] ⚠️ 删除异常:', error.message);
        return false;
    }
}

/**
 * 批量上传图片到 Supabase Storage
 * @param {Array<{base64: string, name: string}>} images - 图片数组
 * @returns {Promise<Array<{url: string, key: string, originalIndex: number}>>} 上传结果数组
 */
export async function uploadMultipleImagesToSupabase(images) {
    console.log('[ImageUploader] 批量上传', images.length, '张图片');

    const results = [];
    for (let i = 0; i < images.length; i++) {
        try {
            const img = images[i];
            console.log(`[ImageUploader] 上传第 ${i + 1}/${images.length} 张图片:`, img.name);

            const uploadResult = await uploadImageToSupabase(img.base64, img.name);
            results.push({
                ...uploadResult,
                originalIndex: i,
                originalName: img.name
            });

        } catch (error) {
            console.error(`[ImageUploader] 第 ${i + 1} 张图片上传失败:`, error);
            // 继续上传其他图片
            results.push({
                error: error.message,
                originalIndex: i,
                originalName: images[i].name
            });
        }
    }

    const successCount = results.filter(r => !r.error).length;
    console.log('[ImageUploader] 批量上传完成:', successCount, '/', images.length, '成功');

    return results;
}
