/**
 * Google Gemini AI API 服务
 * 文档: https://ai.google.dev/gemini-api/docs
 */

// 使用 Cloudflare Worker 代理（隐藏 API Key）
const GEMINI_API_BASE_URL = 'https://ai-chat-proxy.yuc430060.workers.dev';
// const GEMINI_API_BASE_URL = 'https://spb-wz98bgf6x7f3zs9b.supabase.opentrust.net/functions/v1/ai-chat-proxy';
const DEFAULT_MODEL = 'gemini-2.5-flash';

/**
 * Gemini AI 服务类
 * 注意：API Key 已迁移到 Cloudflare Worker，客户端不再需要设置
 */
class GeminiService {
    constructor(apiKey = '') {
        // API Key 已废弃，保留参数仅为兼容性
        this.apiKey = apiKey;
        this.model = DEFAULT_MODEL;
        this.conversationHistory = [];
        this.paperContext = null; // 论文上下文
    }

    /**
     * 设置 API Key（已废弃，保留仅为兼容性）
     */
    setApiKey(apiKey) {
        console.warn('[Gemini] setApiKey 已废弃，API Key 现在由服务端管理');
        this.apiKey = apiKey;
    }

    /**
     * 设置模型
     * @param {string} model - 模型名称
     */
    setModel(model) {
        this.model = model;
    }

    /**
     * 设置论文上下文（Markdown 格式）
     * @param {string} paperMarkdown - 论文的 Markdown 内容
     */
    setPaperContext(paperMarkdown) {
        this.paperContext = paperMarkdown;
        console.log(`[Gemini] 已设置论文上下文，长度: ${paperMarkdown?.length || 0}`);
    }

    /**
     * 检查是否已设置论文上下文
     * @returns {boolean}
     */
    hasPaperContext() {
        return !!this.paperContext;
    }

    /**
     * 清除论文上下文
     */
    clearPaperContext() {
        this.paperContext = null;
        console.log('[Gemini] 已清除论文上下文');
    }

    /**
     * 设置对话历史（用于恢复会话）
     * @param {Array} history - 历史消息数组
     */
    setHistory(history) {
        this.conversationHistory = history.map(msg => ({
            role: msg.role === 'assistant' ? 'model' : msg.role,
            parts: [{ text: msg.content }]
        }));
        console.log(`[Gemini] 已设置对话历史，共 ${this.conversationHistory.length} 条`);
    }

    /**
     * 清除对话历史
     */
    clearHistory() {
        this.conversationHistory = [];
        console.log('[Gemini] 已清除对话历史');
    }

    /**
     * 构建带论文上下文的系统提示
     * @returns {string}
     */
    _buildSystemPrompt() {
        if (!this.paperContext) {
            return '你是一个专业的学术助手，帮助用户理解和分析学术论文。请用中文回答问题。';
        }
        return `你是一个专业的学术助手。以下是用户正在阅读的论文内容：

---论文内容开始---
${this.paperContext}
---论文内容结束---

请基于这篇论文回答用户的问题。如果问题与论文无关，也可以正常回答。请用中文回答。`;
    }

    /**
     * 调用 Gemini AI 对话 API
     * @param {string} userMessage - 用户消息
     * @param {Object} options - 可选配置
     * @returns {Promise<Object>} API 响应
     */
    async chat(userMessage, options = {}) {
        const {
            includeHistory = true,
            temperature = 0.7,
            maxTokens = 8192,
        } = options;

        // API Key 已迁移到 Cloudflare Worker，不再需要客户端检查

        // 构建请求内容
        const contents = [];

        // 添加系统提示作为第一条消息
        const systemPrompt = this._buildSystemPrompt();
        contents.push({
            role: 'user',
            parts: [{ text: systemPrompt }]
        });
        contents.push({
            role: 'model',
            parts: [{ text: '好的，我已经阅读了论文内容，请问有什么问题？' }]
        });

        // 添加历史对话
        if (includeHistory && this.conversationHistory.length > 0) {
            contents.push(...this.conversationHistory);
        }

        // 添加当前用户消息
        contents.push({
            role: 'user',
            parts: [{ text: userMessage }]
        });

        const requestBody = {
            contents: contents,
            generationConfig: {
                temperature: temperature,
                maxOutputTokens: maxTokens,
            }
        };

        try {
            const response = await fetch(GEMINI_API_BASE_URL, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-API-Provider': 'gemini' // 指定使用 Gemini
                },
                body: JSON.stringify({
                    model: this.model,
                    messages: contents.map(c => ({
                        role: c.role === 'model' ? 'assistant' : c.role,
                        content: c.parts[0].text
                    })),
                    temperature,
                    max_tokens: maxTokens
                })
            });

            if (!response.ok) {
                const errorData = await response.json().catch(() => ({}));
                throw new Error(
                    `Gemini API 请求失败: ${response.status} ${response.statusText}. ` +
                    `详情: ${JSON.stringify(errorData)}`
                );
            }

            const data = await response.json();
            const assistantMessage = data.candidates?.[0]?.content?.parts?.[0]?.text || '';

            // 更新对话历史
            if (includeHistory) {
                this.conversationHistory.push({
                    role: 'user',
                    parts: [{ text: userMessage }]
                });
                this.conversationHistory.push({
                    role: 'model',
                    parts: [{ text: assistantMessage }]
                });
            }

            return {
                success: true,
                message: assistantMessage,
                usage: data.usageMetadata || null
            };

        } catch (error) {
            console.error('[Gemini] 对话请求失败:', error);
            return {
                success: false,
                error: error.message,
                message: `抱歉，Gemini AI 服务出现错误: ${error.message}`
            };
        }
    }

    /**
     * 流式对话（SSE）
     * @param {string} userMessage - 用户消息
     * @param {Function} onChunk - 每次收到数据块时的回调，格式：{ done, content, fullMessage, interrupted }
     * @param {Object} options - 可选配置
     * @returns {Promise<Object>} 完整响应
     */
    async chatStream(userMessage, onChunk, options = {}) {
        const {
            includeHistory = true,
            temperature = 0.7,
            maxTokens = 8192,
        } = options;

        // API Key 已迁移到 Cloudflare Worker，不再需要客户端检查

        // 构建请求内容
        const contents = [];

        // 添加系统提示
        const systemPrompt = this._buildSystemPrompt();
        contents.push({
            role: 'user',
            parts: [{ text: systemPrompt }]
        });
        contents.push({
            role: 'model',
            parts: [{ text: '好的，我已经阅读了论文内容，请问有什么问题？' }]
        });

        // 添加历史对话
        if (includeHistory && this.conversationHistory.length > 0) {
            contents.push(...this.conversationHistory);
        }

        // 添加当前用户消息
        contents.push({
            role: 'user',
            parts: [{ text: userMessage }]
        });

        const requestBody = {
            contents: contents,
            generationConfig: {
                temperature: temperature,
                maxOutputTokens: maxTokens,
            }
        };

        let fullMessage = '';
        let lastChunkTime = Date.now();
        const TIMEOUT_MS = 30000; // 30秒超时
        let streamCompleted = false;

        try {
            console.log('[Gemini] 开始流式请求...');

            const response = await fetch(GEMINI_API_BASE_URL, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-API-Provider': 'gemini' // 指定使用 Gemini
                },
                body: JSON.stringify({
                    model: this.model,
                    messages: contents.map(c => ({
                        role: c.role === 'model' ? 'assistant' : c.role,
                        content: c.parts[0].text
                    })),
                    temperature,
                    max_tokens: maxTokens,
                    stream: true
                })
            });

            if (!response.ok) {
                const errorData = await response.json().catch(() => ({}));
                throw new Error(
                    `Gemini API 请求失败: ${response.status} ${response.statusText}. ` +
                    `详情: ${JSON.stringify(errorData)}`
                );
            }

            const reader = response.body.getReader();
            const decoder = new TextDecoder();

            while (true) {
                // 检查超时
                if (Date.now() - lastChunkTime > TIMEOUT_MS) {
                    console.warn('[Gemini] 流式输出超时（30秒无数据）');
                    throw new Error('流式输出超时，连接可能中断');
                }

                const { done, value } = await reader.read();

                if (done) {
                    console.log('[Gemini] 流读取完成，streamCompleted:', streamCompleted);
                    // 流结束
                    if (!streamCompleted && fullMessage) {
                        // 流意外结束但有内容，保存并标记中断
                        console.warn('[Gemini] ⚠️ 流意外结束，可能中断');
                        if (includeHistory) {
                            this.conversationHistory.push({
                                role: 'user',
                                parts: [{ text: userMessage }]
                            });
                            this.conversationHistory.push({
                                role: 'model',
                                parts: [{ text: fullMessage }]
                            });
                        }
                        if (onChunk) {
                            onChunk({
                                done: true,
                                fullMessage,
                                interrupted: true
                            });
                        }
                    }
                    break;
                }

                lastChunkTime = Date.now();
                const chunk = decoder.decode(value, { stream: true });
                const lines = chunk.split('\n').filter(line => line.trim() !== '');

                for (const line of lines) {
                    if (line.startsWith('data: ')) {
                        const jsonStr = line.slice(6);
                        if (jsonStr.trim() === '[DONE]') {
                            // 流式输出正常结束
                            console.log('[Gemini] ✓ 流式输出正常完成');
                            streamCompleted = true;
                            if (includeHistory) {
                                this.conversationHistory.push({
                                    role: 'user',
                                    parts: [{ text: userMessage }]
                                });
                                this.conversationHistory.push({
                                    role: 'model',
                                    parts: [{ text: fullMessage }]
                                });
                            }
                            if (onChunk) {
                                onChunk({ done: true, fullMessage });
                            }
                            return {
                                success: true,
                                message: fullMessage
                            };
                        }

                        try {
                            const parsed = JSON.parse(jsonStr);
                            const text = parsed.candidates?.[0]?.content?.parts?.[0]?.text || '';

                            // 检查 finishReason
                            const finishReason = parsed.candidates?.[0]?.finishReason;
                            if (finishReason) {
                                console.log('[Gemini] finishReason:', finishReason);
                                if (finishReason === 'STOP') {
                                    console.log('[Gemini] ✓ 正常结束');
                                    streamCompleted = true;
                                } else if (finishReason === 'MAX_TOKENS') {
                                    console.warn('[Gemini] ⚠️ 输出因达到 maxOutputTokens 限制而截断');
                                }
                            }

                            if (text) {
                                fullMessage += text;
                                if (onChunk) {
                                    onChunk({
                                        done: false,
                                        content: text,
                                        fullMessage
                                    });
                                }
                            }

                            // 如果收到 finishReason，完成流
                            if (finishReason === 'STOP') {
                                if (includeHistory) {
                                    this.conversationHistory.push({
                                        role: 'user',
                                        parts: [{ text: userMessage }]
                                    });
                                    this.conversationHistory.push({
                                        role: 'model',
                                        parts: [{ text: fullMessage }]
                                    });
                                }
                                if (onChunk) {
                                    onChunk({ done: true, fullMessage });
                                }
                                return {
                                    success: true,
                                    message: fullMessage
                                };
                            }
                        } catch (e) {
                            // 忽略解析错误
                            console.warn('[Gemini] 解析 SSE 数据失败:', line, e);
                        }
                    }
                }
            }

            // 流正常结束（没有收到 [DONE] 或 finishReason: STOP，但流已完成）
            if (!streamCompleted && fullMessage) {
                console.log('[Gemini] 流结束，保存历史');
                if (includeHistory) {
                    this.conversationHistory.push({
                        role: 'user',
                        parts: [{ text: userMessage }]
                    });
                    this.conversationHistory.push({
                        role: 'model',
                        parts: [{ text: fullMessage }]
                    });
                }
                if (onChunk) {
                    onChunk({ done: true, fullMessage });
                }
            }

            return {
                success: true,
                message: fullMessage
            };

        } catch (error) {
            console.error('[Gemini] 流式对话请求失败:', error);
            // 出错时也要通知完成
            if (onChunk) {
                onChunk({
                    done: true,
                    fullMessage: fullMessage || '',
                    interrupted: true,
                    error: error.message
                });
            }
            return {
                success: false,
                error: error.message,
                message: fullMessage || `抱歉，Gemini AI 服务出现错误: ${error.message}`
            };
        }
    }
}

// 导出单例实例
const geminiService = new GeminiService();

export default geminiService;
export { GeminiService };
