import React, { useCallback, useEffect, useRef, useState } from 'react';
import { createEditor, Editor, Range, Transforms } from 'slate';
import { withHistory } from 'slate-history';
import { Editable, Slate, useFocused, useSelected, withReact } from 'slate-react';
import { GlobalOutlined, SendOutlined, DownOutlined, SettingOutlined } from '@ant-design/icons';
import { Button, Flex, theme, Dropdown, message as antMessage, Modal, Form, Input } from 'antd';
import modelIcon from '../icons/model.svg';
import ImageUploader from './ImageUploader';
import ImagePreview from './ImagePreview';
import { uploadImageToSupabase } from './imageR2Uploader';

// VibeCard Mention 组件
const VibeCardMention = ({ attributes, children, element }) => {
    const selected = useSelected();
    const focused = useFocused();

    return (
        <span
            {...attributes}
            contentEditable={false}
            style={{
                padding: '2px 6px',
                margin: '0 2px',
                verticalAlign: 'baseline',
                display: 'inline-block',
                borderRadius: '12px',
                backgroundColor: '#f5f5f5',
                border: '1px solid #e5e5e5',
                color: '#262626',
                fontSize: '0.9em',
                fontWeight: '500',
                boxShadow: selected && focused ? '0 0 0 2px rgba(0,0,0,0.06)' : 'none',
                cursor: 'default',
                transition: 'background-color .2s, border-color .2s, box-shadow .2s',
            }}
        >
            <span contentEditable={false}>
                @{element.vibeCardName || element.vibeCardId}
                {children}
            </span>
        </span>
    );
};

// 元素渲染器
const Element = ({ attributes, children, element }) => {
    switch (element.type) {
        case 'vibecard-mention':
            return <VibeCardMention attributes={attributes} children={children} element={element} />;
        default:
            return <div {...attributes}>{children}</div>;
    }
};

// 叶子节点渲染器
const Leaf = ({ attributes, children }) => {
    return <span {...attributes}>{children}</span>;
};

// 扩展编辑器以支持 VibeCard mentions
const withVibeCardMentions = (editor) => {
    const { isInline, isVoid } = editor;

    editor.isInline = (element) => {
        return element.type === 'vibecard-mention' ? true : isInline(element);
    };

    editor.isVoid = (element) => {
        return element.type === 'vibecard-mention' ? true : isVoid(element);
    };

    return editor;
};

// 插入 VibeCard mention
const insertVibeCardMention = (editor, vibeCardData, targetRange = null, searchText = '') => {
    const mention = {
        type: 'vibecard-mention',
        vibeCardId: vibeCardData.id,
        vibeCardName: vibeCardData.name,
        children: [{ text: '' }],
    };

    if (targetRange) {
        try {
            const endPoint = Range.end(targetRange);
            const distance = (searchText?.length || 0) + 1;
            const anchorPoint = Editor.before(editor, endPoint, { distance, unit: 'character' });
            if (anchorPoint) {
                const exactRange = { anchor: anchorPoint, focus: endPoint };
                Transforms.select(editor, exactRange);
                Transforms.delete(editor);
            } else {
                Transforms.select(editor, targetRange);
                Transforms.delete(editor);
            }
        } catch (err) {
            Transforms.select(editor, targetRange);
            Transforms.delete(editor);
        }
    }

    Transforms.insertNodes(editor, mention);
    Transforms.move(editor);
};

// Slate 输入框组件（使用 Ant Design X Sender 样式）
const SlateInputWithSender = ({
    onSubmit,
    loading,
    onVibeCardInsert,
    onModelChange,
    currentModel  // 接收父组件传入的当前模型
}) => {
    const { token } = theme.useToken();
    const editorRef = useRef();
    if (!editorRef.current) {
        editorRef.current = withVibeCardMentions(withReact(withHistory(createEditor())));
    }
    const editor = editorRef.current;

    const [value, setValue] = useState([
        {
            type: 'paragraph',
            children: [{ text: '' }],
        },
    ]);

    const [webSearchEnabled, setWebSearchEnabled] = useState(false);

    // 自定义模型配置
    const [isConfigModalOpen, setIsConfigModalOpen] = useState(false);
    const [form] = Form.useForm();
    const [customConfig, setCustomConfig] = useState(null);

    // 获取 Zotero 对象的工具函数
    const getZotero = () => {
        return window.Zotero || window.parent?.Zotero || window.top?.Zotero;
    };

    // 读取自定义模型配置（使用 Zotero.Prefs）
    const getCustomModelConfig = () => {
        try {
            const Zotero = getZotero();
            if (Zotero && Zotero.Prefs) {
                const saved = Zotero.Prefs.get('aiChat.customModelConfig', true);
                if (saved) {
                    return JSON.parse(saved);
                }
            }
        } catch (e) {
            console.warn('[SlateInput] Failed to get custom model config:', e);
        }
        return null;
    };

    // 保存自定义模型配置（使用 Zotero.Prefs）
    const saveCustomModelConfig = (config) => {
        try {
            const Zotero = getZotero();
            if (Zotero && Zotero.Prefs) {
                Zotero.Prefs.set('aiChat.customModelConfig', JSON.stringify(config), true);
                return true;
            }
        } catch (e) {
            console.error('[SlateInput] Failed to save custom model config:', e);
        }
        return false;
    };

    // 初始化时读取配置
    useEffect(() => {
        try {
            const savedConfig = getCustomModelConfig();
            if (savedConfig) {
                setCustomConfig(savedConfig);
            }
        } catch (e) {
            console.warn('Failed to parse custom model config:', e);
        }
    }, []);

    // 保存配置
    const handleSaveConfig = () => {
        form.validateFields().then(values => {
            const configToSave = {
                ...values,
                isCustom: true
            };

            if (saveCustomModelConfig(configToSave)) {
                setCustomConfig(configToSave);
                setIsConfigModalOpen(false);
                antMessage.success('自定义模型配置已保存');

                // 自动切换到自定义模型
                if (onModelChange) {
                    onModelChange({
                        key: 'custom',
                        label: `Custom (${values.modelName})`,
                        config: configToSave
                    });
                }
            } else {
                antMessage.error('保存配置失败');
            }
        });
    };

    // 图片状态
    const [attachedImages, setAttachedImages] = useState([]);

    const renderElement = useCallback((props) => <Element {...props} />, []);
    const renderLeaf = useCallback((props) => <Leaf {...props} />, []);

    // 暴露插入 VibeCard 的方法给父组件
    useEffect(() => {
        if (onVibeCardInsert) {
            onVibeCardInsert((vibeCardData) => {
                insertVibeCardMention(editor, vibeCardData);
            });
        }
    }, [editor, onVibeCardInsert]);

    // 提取纯文本和 VibeCard 引用
    const extractContent = () => {
        const text = editor.children
            .map((node) => {
                return node.children
                    .map((child) => {
                        if (child.type === 'vibecard-mention') {
                            // 使用 name 而不是 id，确保与替换逻辑一致
                            return `@${child.vibeCardName || child.vibeCardId}`;
                        }
                        return child.text || '';
                    })
                    .join('');
            })
            .join('\n');

        const vibeCardRefs = [];
        editor.children.forEach((node) => {
            node.children.forEach((child) => {
                if (child.type === 'vibecard-mention') {
                    vibeCardRefs.push({
                        id: child.vibeCardId,
                        name: child.vibeCardName || child.vibeCardId
                    });
                }
            });
        });

        return { text, vibeCardRefs };
    };

    // 检查编辑器是否为空（包括图片）
    const isEditorEmpty = () => {
        const { text, vibeCardRefs } = extractContent();
        return !text.trim() && vibeCardRefs.length === 0 && attachedImages.length === 0;
    };

    // 处理图片选择（自动上传到 Supabase Storage）
    const handleImageSelect = useCallback(async (imageData) => {
        // console.log('[SlateInput] 图片已选择:', imageData.type, imageData.name);

        // 显示上传中的提示
        const hideLoading = antMessage.loading('正在上传图片到云存储...', 0);

        try {
            // 上传到 Supabase Storage 获取公开 URL
            // console.log('[SlateInput] 开始上传图片到 Supabase Storage...');
            const uploadResult = await uploadImageToSupabase(imageData.base64, imageData.name);

            // console.log('[SlateInput] ✅ 图片上传成功:', uploadResult.url);

            // 保存图片信息（包含 Supabase URL 和原始 base64）
            const imageWithUrl = {
                ...imageData,
                r2Url: uploadResult.url,      // Supabase 公开 URL（用于发送给 AI）
                r2Key: uploadResult.key,       // Supabase 文件 key（用于删除）
                base64: imageData.base64       // 保留 base64（用于本地显示）
            };

            setAttachedImages(prev => [...prev, imageWithUrl]);
            hideLoading();
            antMessage.success('图片上传成功');

        } catch (error) {
            console.error('[SlateInput] ❌ 图片上传失败:', error);
            hideLoading();
            antMessage.error('图片上传失败: ' + error.message);
        }
    }, []);

    // 移除图片
    const handleImageRemove = useCallback((index) => {
        setAttachedImages(prev => prev.filter((_, i) => i !== index));
    }, []);

    // 内部提交状态，防止快速重复点击导致的竞态问题
    // 使用 useRef 而非 useState，因为 ref 更新是同步的，可以立即阻止第二次回车
    const submittingRef = useRef(false);

    // 处理发送
    const handleSubmit = useCallback(async () => {
        // 防止重复提交：检查 loading (父组件状态) 和 submittingRef (本地同步锁)
        if (isEditorEmpty() || loading || submittingRef.current) return;

        // 立即设置本地提交状态（同步更新，立即生效）
        submittingRef.current = true;

        try {
            // 基本检查：只做同步的快速检查，耗时检查（如余额）移到父组件
            const Zotero = window.Zotero || window.parent?.Zotero || window.top?.Zotero;
            if (!Zotero || !Zotero.VibeDBSync) {
                console.error('[SlateInput/handleSubmit] 无法访问 Zotero.VibeDBSync');
                antMessage.error('系统错误，请重启 Zotero');
                return;
            }

            // 1. 检查登录状态（同步检查，不阻塞）
            // 使用 VibeDBSync.ensureLoggedIn 统一处理（它会自动尝试打开登录面板）
            if (Zotero.VibeDBSync.ensureLoggedIn && !Zotero.VibeDBSync.ensureLoggedIn()) {
                antMessage.warning('请登录账号以继续使用');
                return;
            }

            // 提取内容
            const { text, vibeCardRefs } = extractContent();

            // 先保存当前的图片数组（避免被清空前就丢失）
            const imagesToSend = [...attachedImages];

            // 立即清空 UI（提升用户体验，不等待 onSubmit 返回）
            Transforms.delete(editor, {
                at: {
                    anchor: Editor.start(editor, []),
                    focus: Editor.end(editor, []),
                },
            });
            setAttachedImages([]);

            // 调用父组件的 onSubmit（父组件会设置 loading 状态并进行余额检查）
            // 注意：不再等待结果，让父组件处理后续逻辑
            onSubmit(text, vibeCardRefs, imagesToSend);

        } catch (e) {
            console.error('[SlateInput] handleSubmit execution failed:', e);
            antMessage.error('发送失败: ' + e.message);
        } finally {
            submittingRef.current = false;
        }
    }, [loading, attachedImages, editor, onSubmit]);

    // 处理键盘事件
    const handleKeyDown = useCallback(
        (event) => {
            // Enter 提交（Shift+Enter 换行）
            if (event.key === 'Enter' && !event.shiftKey) {
                event.preventDefault();
                // 禁用状态下不允许提交（检查 loading 和 submittingRef）
                // submittingRef.current 是同步值，可以立即阻止第二次回车
                if (loading || submittingRef.current || isEditorEmpty()) {
                    return;
                }
                handleSubmit();
            }
        },
        [loading, attachedImages, handleSubmit]
    );

    // 处理拖拽放置事件（VibeCard 引用）
    const handleDrop = useCallback(
        (event) => {
            // 检查是否是 VibeCard 拖拽
            const vibeCardData = event.dataTransfer.getData('application/x-zotero-vibecard-reference');
            if (vibeCardData) {
                event.preventDefault();
                event.stopPropagation();

                try {
                    const data = JSON.parse(vibeCardData);
                    // console.log('[SlateInput] VibeCard dropped:', data);

                    if (data.vibeCardId) {
                        // 插入 VibeCard mention
                        insertVibeCardMention(editor, {
                            id: data.vibeCardId,
                            name: data.vibeCardName || data.vibeCardId,
                            type: data.type,
                            vibeCardType: data.vibeCardType
                        });
                        // console.log('[SlateInput] VibeCard mention inserted:', data);
                    }
                } catch (error) {
                    console.error('[SlateInput] Error parsing VibeCard drop data:', error);
                }
            }
            // 如果不是 VibeCard，让浏览器处理默认的文本拖拽
        },
        [editor]
    );

    // 处理拖拽悬停事件
    const handleDragOver = useCallback(
        (event) => {
            // 检查是否是 VibeCard 拖拽
            const types = event.dataTransfer.types;
            if (types.includes('application/x-zotero-vibecard-reference')) {
                event.preventDefault();
                event.stopPropagation();
                event.dataTransfer.dropEffect = 'copy';
            }
        },
        []
    );

    const handleChange = useCallback(
        (newValue) => {
            setValue(newValue);
        },
        []
    );

    const iconStyle = {
        fontSize: 18,
        color: token.colorText,
    };

    // 模型选择菜单（Doubao 支持多模态，放在第一位）
    const modelMenuItems = [
        {
            key: 'doubao',
            label: 'Doubao(多模态)',
            disabled: false,
        },
        {
            key: 'GLM-4.6',
            label: 'GLM',
            disabled: false,
        },
        {
            key: 'deepseek',
            label: 'Deepseek',
            disabled: false,
        },
        {
            key: 'gemini',
            label: 'Gemini(多模态)',
            disabled: true, // 暂时禁用
        },
        {
            type: 'divider'
        },
        {
            key: 'custom',
            label: (
                <Flex justify="space-between" align="center" style={{ width: '100%', minWidth: 120 }}>
                    <span>Custom Model</span>
                    <Button
                        type="text"
                        size="small"
                        icon={<SettingOutlined />}
                        onClick={(e) => {
                            e.stopPropagation();
                            try {
                                console.log('[SlateInput] Opening custom model config modal...');
                                setIsConfigModalOpen(true);
                                // 如果有保存的配置，回填表单
                                const savedConfig = getCustomModelConfig();
                                console.log('[SlateInput] Saved config:', savedConfig);
                                if (savedConfig) {
                                    form.setFieldsValue(savedConfig);
                                }
                            } catch (err) {
                                console.error('[SlateInput] Error opening config modal:', err);
                                antMessage.error('打开配置弹窗失败: ' + err.message);
                            }
                        }}
                    />
                </Flex>
            ),
        }
    ];

    const handleModelSelect = ({ key }) => {
        // 如果点击的是 custom 且没有配置，自动打开弹窗
        if (key === 'custom') {
            try {
                const savedConfig = getCustomModelConfig();
                if (!savedConfig) {
                    setIsConfigModalOpen(true);
                    return;
                }
                // 有配置直接切换
                if (onModelChange) {
                    onModelChange({
                        key: 'custom',
                        label: `Custom (${savedConfig.modelName})`,
                        config: savedConfig  // 传递配置给父组件
                    });
                }
            } catch (err) {
                console.error('[SlateInput] Error selecting custom model:', err);
                antMessage.error('加载自定义模型配置失败: ' + err.message);
            }
            return;
        }

        const selectedItem = modelMenuItems.find(item => item.key === key);
        if (selectedItem && !selectedItem.disabled) {
            // 通知父组件模型变更
            if (onModelChange) {
                onModelChange({
                    key: key,
                    label: selectedItem.label
                });
            }
        }
    };

    // 使用父组件传入的 currentModel，如果没有则使用默认值
    // 对于 custom model，动态从配置读取最新的模型名称
    const displayModel = (() => {
        if (currentModel?.key === 'custom') {
            const latestConfig = getCustomModelConfig();
            if (latestConfig && latestConfig.modelName) {
                return `Custom (${latestConfig.modelName})`;
            }
            return 'Custom Model';
        }
        return currentModel?.label || 'Doubao';
    })();

    return (
        <div
            style={{
                background: 'var(--material-background, #ffffff)',
                border: '1px solid var(--fill-quinary, #e0e0e0)',
                borderRadius: '8px',
                transition: 'border-color 0.2s, box-shadow 0.2s',
            }}
            className="slate-sender-container"
        >
            {/* 图片预览区域 */}
            <ImagePreview
                images={attachedImages}
                onRemove={handleImageRemove}
            />

            {/* Slate 编辑器区域 */}
            <div style={{ padding: '8px 12px' }}>
                <Slate editor={editor} initialValue={value} onChange={handleChange}>
                    <Editable
                        renderElement={renderElement}
                        renderLeaf={renderLeaf}
                        onKeyDown={handleKeyDown}
                        onDrop={handleDrop}
                        onDragOver={handleDragOver}
                        placeholder="Press Enter to send message"
                        disabled={loading}
                        style={{
                            minHeight: '36px',
                            maxHeight: '120px',
                            fontSize: '14px',
                            color: 'var(--fill-primary, #333)',
                            outline: 'none',
                            overflowY: 'auto',
                            lineHeight: '1.5',
                        }}
                    />
                </Slate>
            </div>

            {/* Footer 工具栏 */}
            <div
                style={{
                    padding: '8px 12px',
                    borderTop: '1px solid var(--fill-quinary, #f0f0f0)',
                }}
            >
                <Flex justify="space-between" align="center">
                    {/* 左侧工具 */}
                    <Flex gap="small" align="center">
                        {/* 图片上传和截图按钮 */}
                        <ImageUploader
                            onImageSelect={handleImageSelect}
                            iconStyle={iconStyle}
                        />
                        <Button
                            type="text"
                            icon={<GlobalOutlined />}
                            onClick={() => setWebSearchEnabled(!webSearchEnabled)}
                            title="Web Search"
                            className={webSearchEnabled ? 'icon-btn-active' : ''}
                            style={iconStyle}
                        />
                        <Dropdown
                            menu={{
                                items: modelMenuItems.map(item => ({
                                    ...item,
                                    // 当前选中的模型显示勾选标记
                                    icon: currentModel?.key === item.key ? '✓' : null
                                })),
                                onClick: handleModelSelect,
                                className: 'model-dropdown-menu',
                                selectedKeys: currentModel ? [currentModel.key] : ['doubao']
                            }}
                            trigger={['click']}
                        >
                            <Button
                                type="text"
                                style={iconStyle}
                                title={`当前模型: ${displayModel}`}
                            >
                                <img src={modelIcon} alt="model" style={{ width: 18, height: 18, marginRight: 4 }} />
                                <span style={{ marginRight: 4, fontSize: 14 }}>{displayModel}</span>
                                <DownOutlined style={{ fontSize: 12 }} />
                            </Button>
                        </Dropdown>
                    </Flex>

                    {/* 右侧工具 */}
                    <Flex align="center" gap="small">
                        <Button
                            className="btn-black"
                            icon={<SendOutlined />}
                            loading={loading}
                            disabled={isEditorEmpty()}
                            onClick={handleSubmit}
                        >
                            Send
                        </Button>
                    </Flex>
                </Flex>
            </div>

            {/* 自定义模型配置弹窗 */}
            <Modal
                title="配置自定义模型 (OpenAI 兼容)"
                open={isConfigModalOpen}
                onOk={handleSaveConfig}
                onCancel={() => setIsConfigModalOpen(false)}
                okText="保存并使用"
                cancelText="取消"
                destroyOnClose
                zIndex={10001}
                centered
                getContainer={false}
                wrapClassName="ai-chat-modal"
            >
                <Form form={form} layout="vertical" preserve={false}>
                    <Form.Item
                        label="API Base URL"
                        name="baseUrl"
                        tooltip="接口基地址，例如: https://api.openai.com/v1"
                        rules={[{ required: true, message: '请输入 Base URL' }]}
                    >
                        <Input placeholder="https://api.openai.com/v1" />
                    </Form.Item>
                    <Form.Item
                        label="API Key"
                        name="apiKey"
                        rules={[{ required: true, message: '请输入 API Key' }]}
                    >
                        <Input.Password
                            placeholder="sk-..."
                            autoComplete="off"
                            visibilityToggle={false}
                        />
                    </Form.Item>
                    <Form.Item
                        label="模型名称 (Model Name)"
                        name="modelName"
                        tooltip="调用的模型ID，例如: gpt-4o, deepseek-chat"
                        rules={[{ required: true, message: '请输入模型名称' }]}
                    >
                        <Input placeholder="gpt-4o" />
                    </Form.Item>
                </Form>
            </Modal>
        </div>
    );
};

export default SlateInputWithSender;
